entries[19955] = { ["name"] = "Wushoolay's Charm of Nature", ["text"] = "Binds when picked up\nUnique\nTrinket\nClasses: Druid\nRequires Level 60\nUse: Grants 70 spell haste rating, and reduces the mana cost of Rejuvenation, Healing Touch, Regrowth, and Tranquility by 5% for 15 sec. (3 Min Cooldown)\n\nHaruspex's Garb (0/5)\nPristine Enchanted South Seas Kelp\nWushoolay's Charm of Nature\nZandalar Haruspex's Bracers\nZandalar Haruspex's Belt\nZandalar Haruspex's Tunic\n(2) Set : Restores 4 mana per 5 sec.\n(3) Set : Increases the duration of Faerie Fire by 5 sec.\n(5) Set : Increases the critical hit chance of your Starfire spell 3%." }
entries[19956] = { ["name"] = "Wushoolay's Charm of Spirits", ["text"] = "Binds when picked up\nUnique\nTrinket\nClasses: Shaman\nRequires Level 60\nUse: Increases the damage dealt by your Lightning Shield spell by 305 for 20 sec. (3 Min Cooldown)\n\nAugur's Regalia (0/5)\nUnmarred Vision of Voodress\nWushoolay's Charm of Spirits\nZandalar Augur's Bracers\nZandalar Augur's Belt\nZandalar Augur's Hauberk\n(2) Set : Restores 4 mana per 5 sec.\n(3) Set : Improves the duration of your Frost Shock spell by 1 sec.\n(5) Set : Increase the range of your Lightning Bolt spell by 5 yds." }
entries[19957] = { ["name"] = "Hazza'rah's Charm of Destruction", ["text"] = "Binds when picked up\nUnique\nTrinket\nClasses: Warlock\nRequires Level 60\nUse: Increases your spell critical strike rating by 140 for 20 sec. (3 Min Cooldown)\n\nDemoniac's Threads (0/5)\nKezan's Unstoppable Taint\nHazza'rah's Charm of Destruction\nZandalar Demoniac's Wraps\nZandalar Demoniac's Mantle\nZandalar Demoniac's Robe\n(2) Set : Increases damage and healing done by magical spells and effects by up to 12.\n(3) Set : Increases the damage of Corruption by 2%.\n(5) Set : Decreases the cooldown of Death Coil by 15%." }
